DATASET_CONNECTOR_HTML = r"""
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Dataset Connector</title>
<style>
:root{--bg:#050b16;--panel:#0b1424;--panel2:#0e1a2d;--line:rgba(255,255,255,.09);--text:#eef5ff;--muted:#8ea2bb;--cyan:#22d3ee;--green:#4ade80;--amber:#fbbf24;--red:#fb7185;--shadow:0 16px 50px rgba(0,0,0,.28)}
*{box-sizing:border-box}html{background:var(--bg)}body{margin:0;min-height:100vh;color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:radial-gradient(circle at 10% 0%,rgba(34,211,238,.08),transparent 28%),radial-gradient(circle at 100% 10%,rgba(96,165,250,.07),transparent 24%),var(--bg)}
button,input{font:inherit}button{border:1px solid var(--line);border-radius:10px;min-height:40px;padding:9px 14px;color:var(--text);background:var(--panel2);cursor:pointer;transition:.16s ease}button:hover:not(:disabled){transform:translateY(-1px);border-color:rgba(255,255,255,.17)}button:disabled{opacity:.4;cursor:not-allowed}button.primary{background:linear-gradient(135deg,#22d3ee,#38bdf8);color:#06202b;border-color:transparent;font-weight:750}button.danger{color:#ffd9df;border-color:rgba(251,113,133,.25)}
input[type=file]{width:100%;padding:9px;border-radius:10px;color:var(--muted);background:#071122;border:1px solid var(--line)}
.container{width:min(1450px,calc(100% - 28px));margin:auto;padding:18px 0 28px}header{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:16px}h1{margin:0;font-size:22px;letter-spacing:-.02em}.subtitle{margin-top:5px;color:var(--muted);font-size:13px;line-height:1.5}.header-meta{display:flex;flex-wrap:wrap;gap:8px;justify-content:flex-end}.pill{display:inline-flex;align-items:center;gap:7px;border:1px solid var(--line);background:rgba(255,255,255,.025);padding:7px 10px;border-radius:999px;color:var(--muted);font-size:12px}.dot{width:8px;height:8px;border-radius:50%;background:var(--muted)}.dot.ok{background:var(--green)}.dot.warn{background:var(--amber)}.dot.err{background:var(--red)}.dot.live{background:var(--cyan);box-shadow:0 0 0 5px rgba(34,211,238,.08)}
.banner{display:none;padding:12px 14px;margin-bottom:16px;border-radius:12px;border:1px solid var(--line);background:var(--panel);box-shadow:var(--shadow);font-size:13px}.banner.show{display:block}.banner.error{border-color:rgba(251,113,133,.3);color:#ffd6dd}.banner.info{border-color:rgba(34,211,238,.3);color:#cff8ff}
.layout{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(340px,.85fr);gap:16px;align-items:start}.card{background:rgba(11,20,36,.9);border:1px solid var(--line);border-radius:15px;box-shadow:var(--shadow);overflow:hidden}.card-head{padding:15px 16px 12px;border-bottom:1px solid var(--line)}.card-head strong{font-size:14px}.card-head p{margin:5px 0 0;font-size:12px;color:var(--muted);line-height:1.45}.stream{padding:12px}.stream-box{position:relative;background:#02050a;border:1px solid rgba(255,255,255,.06);border-radius:12px;overflow:hidden}.stream-box img{display:block;width:100%;height:auto;aspect-ratio:4/3;object-fit:contain;background:#000}.stream-foot{display:flex;justify-content:space-between;gap:12px;padding:10px 2px 0;color:var(--muted);font-size:12px}.control-stack{display:grid;gap:12px;padding:12px}.section{border:1px solid var(--line);border-radius:12px;background:rgba(255,255,255,.018)}.section-body{padding:13px;display:grid;gap:10px}.section-title{font-size:13px;font-weight:700}.note{font-size:11px;color:var(--muted);line-height:1.5}.status-line{display:flex;align-items:center;justify-content:space-between;gap:10px}.status-label{font-size:12px;color:var(--muted)}.status-value{font-size:13px;font-weight:650;text-align:right}
.badge{display:inline-flex;align-items:center;justify-content:center;min-height:27px;padding:5px 9px;border-radius:999px;font-size:11px;font-weight:800;border:1px solid var(--line)}.badge.ok{background:rgba(74,222,128,.1);border-color:rgba(74,222,128,.25);color:#baf7cd}.badge.warn{background:rgba(251,191,36,.1);border-color:rgba(251,191,36,.24);color:#ffe9aa}.badge.err{background:rgba(251,113,133,.1);border-color:rgba(251,113,133,.25);color:#ffd5dd}.badge.muted{background:rgba(255,255,255,.03);color:var(--muted)}
.actions{display:flex;gap:8px;flex-wrap:wrap}.actions>*{flex:1 1 145px}.mode-switch{display:grid;grid-template-columns:1fr 1fr;gap:8px}.mode-button.active{border-color:rgba(34,211,238,.5);background:rgba(34,211,238,.1);box-shadow:0 0 0 1px rgba(34,211,238,.12) inset}.metric-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.metric{padding:9px;border-radius:9px;background:rgba(255,255,255,.02);border:1px solid rgba(255,255,255,.05)}.metric span{display:block;font-size:10px;color:var(--muted)}.metric strong{display:block;margin-top:3px;font-size:12px}.gallery-card{margin-top:16px}.gallery{padding:12px;display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px}.capture-card{display:grid;gap:7px;padding:7px;border:1px solid var(--line);border-radius:11px;background:#071122}.capture-card img{display:block;width:100%;height:135px;object-fit:cover;background:#000;border-radius:8px;cursor:zoom-in}.capture-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:10px;color:var(--muted)}.capture-card-actions{display:flex;gap:6px}.capture-card-actions button{min-height:34px;padding:7px 9px;font-size:11px;flex:1}.capture-empty{padding:26px;text-align:center;color:var(--muted);font-size:12px;border:1px dashed var(--line);border-radius:10px}.modal{position:fixed;inset:0;display:none;align-items:center;justify-content:center;padding:20px;background:rgba(0,0,0,.84);z-index:20}.modal.show{display:flex}.modal-card{width:min(1100px,96vw);max-height:92vh;background:var(--panel);border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow);padding:12px;display:grid;gap:10px}.modal-head{display:flex;align-items:center;justify-content:space-between;color:var(--muted);font-size:12px}.modal img{display:block;width:100%;max-height:78vh;object-fit:contain;background:#000;border-radius:10px}
@media(max-width:1050px){.layout{grid-template-columns:1fr}.header-meta{justify-content:flex-start}}@media(max-width:640px){.container{width:min(100% - 14px,1450px);padding-top:10px}header{display:block}.header-meta{margin-top:10px}.mode-switch{grid-template-columns:1fr}.gallery{grid-template-columns:repeat(2,minmax(0,1fr))}.capture-card img{height:125px}}
</style>
</head>
<body>
<div class="container">
<header><div><h1>Dataset Connector</h1><div class="subtitle">Capture camera source frames, review them instantly, and optionally inspect them through a validated camera calibration model. Original captures are never overwritten.</div></div>
<div class="header-meta"><div class="pill"><span id="camera_dot" class="dot"></span><span id="camera_meta">Camera waiting</span></div><div class="pill"><span class="dot live"></span><span id="fps_meta">— FPS</span></div><div class="pill"><span id="calibration_dot" class="dot warn"></span><span id="calibration_meta">No calibration</span></div></div></header>
<div id="banner" class="banner"></div>
<div class="layout">
<section class="card"><div class="card-head"><strong>Live camera</strong><p>The backend owns camera capture. Preview mode changes only what is displayed; saved images remain raw source frames.</p></div><div class="stream"><div class="stream-box"><img src="/video_feed" alt="Live dataset camera stream"></div><div class="stream-foot"><span id="preview_meta">Preview: RAW</span><span id="camera_error">Camera ready</span></div></div>
<div class="control-stack"><div class="section"><div class="section-body"><div class="section-title">Preview mode</div><div class="mode-switch"><button id="mode_raw" class="mode-button active" type="button">Raw</button><button id="mode_calibrated" class="mode-button" type="button" disabled>Calibrated</button></div><div id="preview_note" class="note">Raw mode shows the original camera frame.</div></div></div>
<div class="section"><div class="section-body"><div class="section-title">Capture</div><div class="actions"><button id="capture" class="primary" type="button">Capture frame</button><button id="download" type="button">Download dataset ZIP</button></div><div id="capture_message" class="note">Ready for capture.</div></div></div></div></section>
<aside class="card"><div class="card-head"><strong>Dataset workspace</strong><p>Keep captured images isolated from the canonical training dataset.</p></div><div class="control-stack">
<div class="section"><div class="section-body"><div class="status-line"><span class="status-label">Captured images</span><span id="count" class="badge muted">0</span></div><div class="metric-grid"><div class="metric"><span>Resolution</span><strong id="resolution">—</strong></div><div class="metric"><span>Camera FPS</span><strong id="camera_fps">—</strong></div></div></div></div>
<div class="section"><div class="section-body"><div class="section-title">Camera calibration</div><input id="calibration_file" type="file" accept=".npz,application/octet-stream"><div class="actions"><button id="upload_calibration" type="button">Upload & validate</button><button id="download_calibration" type="button" disabled>Download active</button></div><div id="calibration_note" class="note">Optional. Without a calibration file, the connector remains fully usable in Raw mode.</div></div></div>
<div class="section"><div class="section-body"><div class="section-title">Dataset actions</div><div class="actions"><button id="refresh" type="button">Refresh gallery</button><button id="clear" class="danger" type="button">Clear all</button></div><div class="note">Clear removes only this connector's captured images. It does not touch <code>train_sign_detector/dataset</code>.</div></div></div>
</div></aside></div>
<section class="card gallery-card"><div class="card-head"><strong>Captured images</strong><p id="gallery_meta">0 images</p></div><div id="gallery" class="gallery"><div class="capture-empty">No captures yet. The next frame you capture will appear here.</div></div></section>
</div>
<div id="modal" class="modal"><div class="modal-card"><div class="modal-head"><span id="modal_name">Preview</span><button id="modal_close" type="button">Close</button></div><img id="modal_image" alt="Captured image preview"></div></div>
<script>
const $=id=>document.getElementById(id);let previewMode="raw",calibrationAvailable=false;
function showBanner(message,kind="info"){const el=$("banner");el.textContent=message;el.className=`banner show ${kind}`;clearTimeout(showBanner.timer);showBanner.timer=setTimeout(()=>el.className="banner",4500)}
async function api(url,options={}){const response=await fetch(url,{cache:"no-store",...options});const type=response.headers.get("content-type")||"";const payload=type.includes("application/json")?await response.json():null;if(!response.ok)throw new Error(payload?.message||`Request failed (${response.status})`);return payload}
function updateModeButtons(){$("mode_raw").classList.toggle("active",previewMode==="raw");$("mode_calibrated").classList.toggle("active",previewMode==="calibrated");$("mode_calibrated").disabled=!calibrationAvailable;$("preview_meta").textContent=`Preview: ${previewMode.toUpperCase()}`}
function renderStatus(s){calibrationAvailable=Boolean(s.calibration?.available);previewMode=s.preview_mode||"raw";$("count").textContent=s.captured_images??0;const res=s.camera?.resolution||[];$("resolution").textContent=res.length===2?res.join(" × "):"—";const fps=Number(s.camera?.measured_fps||s.camera?.requested_fps||0).toFixed(1);$("camera_fps").textContent=fps;$("fps_meta").textContent=`${fps} FPS`;$("camera_meta").textContent=s.camera?.initialized?"Camera connected":"Camera unavailable";$("camera_dot").className=`dot ${s.camera?.initialized?"ok":"err"}`;$("camera_error").textContent=s.camera?.last_error||"Camera ready";$("calibration_dot").className=`dot ${calibrationAvailable?"ok":"warn"}`;$("calibration_meta").textContent=calibrationAvailable?`${s.calibration.quality_status||"Calibration ready"}`:"No calibration";$("download_calibration").disabled=!calibrationAvailable;$("calibration_note").textContent=calibrationAvailable?`Active model: ${s.calibration.filename||"camera_calibration.npz"} · ${s.calibration.image_size?s.calibration.image_size.join(" × "):"size not specified"}`:(s.calibration.error||"Optional. Without a calibration file, the connector remains fully usable in Raw mode.");$("preview_note").textContent=previewMode==="calibrated"?"Calibrated mode undistorts the live preview and gallery representation. Source captures stay unchanged.":"Raw mode shows the original camera frame.";updateModeButtons()}
async function refreshStatus(){try{renderStatus(await api("/api/status"))}catch(err){showBanner(err.message,"error")}setTimeout(refreshStatus,1200)}
function galleryUrl(url){return previewMode==="calibrated"?`${url}?view=calibrated`:url}
async function refreshGallery(){try{const data=await api("/api/captures"),gallery=$("gallery");$("gallery_meta").textContent=`${data.captures.length} image${data.captures.length===1?"":"s"}`;gallery.innerHTML="";if(!data.captures.length){gallery.innerHTML='<div class="capture-empty">No captures yet. The next frame you capture will appear here.</div>';return}for(const item of data.captures){const card=document.createElement("div");card.className="capture-card";const img=document.createElement("img");img.src=galleryUrl(item.url);img.alt=item.filename;img.loading="lazy";img.addEventListener("click",()=>openModal(item));const name=document.createElement("div");name.className="capture-name";name.textContent=item.filename;const actions=document.createElement("div");actions.className="capture-card-actions";const open=document.createElement("button");open.type="button";open.textContent="Open";open.addEventListener("click",()=>openModal(item));const remove=document.createElement("button");remove.type="button";remove.textContent="Delete";remove.addEventListener("click",async()=>{if(!confirm(`Delete ${item.filename}?`))return;try{await api(`/api/captures/${encodeURIComponent(item.filename)}`,{method:"DELETE"});await refreshGallery();await refreshStatus();showBanner(`${item.filename} deleted.`)}catch(err){showBanner(err.message,"error")}});actions.append(open,remove);card.append(img,name,actions);gallery.appendChild(card)}}catch(err){showBanner(err.message,"error")}}
function openModal(item){$("modal_name").textContent=item.filename;$("modal_image").src=galleryUrl(item.url);$("modal").classList.add("show")}function closeModal(){$("modal").classList.remove("show");$("modal_image").removeAttribute("src")}
$("capture").addEventListener("click",async()=>{$("capture").disabled=true;try{const r=await api("/api/capture",{method:"POST"});$("capture_message").textContent=r.message;await refreshGallery();await refreshStatus();showBanner(r.message)}catch(err){$("capture_message").textContent=err.message;showBanner(err.message,"error")}finally{$("capture").disabled=false}})
$("download").addEventListener("click",()=>window.location.href="/api/dataset/download");
$("refresh").addEventListener("click",async()=>{await refreshGallery();await refreshStatus()});
$("clear").addEventListener("click",async()=>{if(!confirm("Clear every captured dataset image?"))return;try{const r=await api("/api/clear",{method:"POST"});await refreshGallery();await refreshStatus();showBanner(r.message)}catch(err){showBanner(err.message,"error")}})
async function setMode(mode){try{const r=await api("/api/preview",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({mode})});previewMode=r.preview_mode;await refreshGallery();await refreshStatus()}catch(err){showBanner(err.message,"error")}}
$("mode_raw").addEventListener("click",()=>setMode("raw"));$("mode_calibrated").addEventListener("click",()=>setMode("calibrated"));
$("upload_calibration").addEventListener("click",async()=>{const file=$("calibration_file").files[0];if(!file){showBanner("Choose a .npz calibration file first.","error");return}const form=new FormData();form.append("file",file);$("upload_calibration").disabled=true;try{const r=await api("/api/calibration/upload",{method:"POST",body:form});showBanner(r.message);$("calibration_file").value="";await refreshStatus()}catch(err){showBanner(err.message,"error")}finally{$("upload_calibration").disabled=false}});
$("download_calibration").addEventListener("click",()=>window.location.href="/api/calibration/download");$("modal_close").addEventListener("click",closeModal);$("modal").addEventListener("click",e=>{if(e.target===$("modal"))closeModal()});document.addEventListener("keydown",e=>{if(e.key==="Escape")closeModal()});
refreshGallery();refreshStatus();
</script></body></html>
"""
